help.learn answer:
usage: careerbrew learn answer [-h] --result {correct,partial,wrong,dontknow}
                               --confidence {low,medium,high} --level
                               {remember,understand,apply,analyze,evaluate,create}
                               [--mode {pretest,teach,quiz,recall,review,retest,task}]
                               [--kind {mcq,open,task}] [--seconds SECONDS]
                               project concept

positional arguments:
  project
  concept

options:
  -h, --help            show this help message and exit
  --result {correct,partial,wrong,dontknow}
  --confidence {low,medium,high}
  --level {remember,understand,apply,analyze,evaluate,create}
                        the question's Bloom level
  --mode {pretest,teach,quiz,recall,review,retest,task}
  --kind {mcq,open,task}
                        the question's format, kept in the log
  --seconds SECONDS

